import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        String[] a = new String[n];
        for (int i = 0; i < n; i++) a[i] = next();
        // Digits are independent: each needs |x - y| unit steps.
        long answer = 0;
        for (int i = 0; i < n; i++) {
            String b = next();
            int len = Math.min(a[i].length(), b.length());
            for (int k = 0; k < len; k++) answer += Math.abs(a[i].charAt(k) - b.charAt(k));
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]string, n)
	for i := range a {
		a[i] = nextToken()
	}
	// Digits are independent: each needs |x - y| unit steps.
	var answer int64
	for i := 0; i < n; i++ {
		b := nextToken()
		for k := 0; k < min(len(a[i]), len(b)); k++ {
			d := int64(a[i][k]) - int64(b[k])
			if d < 0 {
				d = -d
			}
			answer += d
		}
	}
	fmt.Println(answer)
}
